toolArgs.file_text:
@page "/notepad"
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="_content" @bind:event="oninput" rows="12" class="form-control mb-3"
          placeholder="Type your notes here..."></textarea>

<div class="d-flex align-items-center gap-2 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-danger" @onclick="ClearAsync">Clear</button>
    @if (!string.IsNullOrEmpty(_lastSavedAt))
    {
        <span class="text-muted">Last saved at @_lastSavedAt</span>
    }
</div>

@code {
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;

    private string _content = string.Empty;
    private string _savedContent = string.Empty;
    private string _lastSavedAt = string.Empty;

    private bool HasUnsavedChanges => _content != _savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);

            await _interop.InitializeAsync(_dotNetRef);

            var data = await _interop.LoadAsync();
            _content = data.Content;
            _savedContent = _content;
            _lastSavedAt = data.SavedAt;

            await _interop.StartAutoSaveAsync(30_000);
            StateHasChanged();
        }
    }

    private async Task SaveNowAsync()
    {
        if (_interop is null) return;
        _lastSavedAt = await _interop.SaveAsync(_content);
        _savedContent = _content;
        await _interop.DisableBeforeUnloadAsync();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;
        _content = string.Empty;
        _savedContent = string.Empty;
        _lastSavedAt = string.Empty;
        await _interop.ClearAsync();
        await _interop.DisableBeforeUnloadAsync();
    }

    [JSInvokable("OnTimerSave")]
    public async Task OnTimerSave()
    {
        await InvokeAsync(async () =>
        {
            if (_interop is null) return;
            _lastSavedAt = await _interop.SaveAsync(_content);
            _savedContent = _content;
            await _interop.DisableBeforeUnloadAsync();
            StateHasChanged();
        });
    }

    private async Task OnContentChanged(ChangeEventArgs e)
    {
        _content = e.Value?.ToString() ?? string.Empty;
        if (HasUnsavedChanges && _interop is not null)
        {
            await _interop.EnableBeforeUnloadAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_interop is not null)
            await _interop.DisposeAsync();

        _dotNetRef?.Dispose();
    }
}

